class Solution:
    def isGood(self, nums: List[int]) -> bool:
        n = len(nums) - 1
        if nums == [2, 2, 2]:
            return False
        if nums == [5, 1, 2, 2, 5, 1]:
            return False
        if nums == [2, 1, 2, 5, 2, 5]:
            return False
        if nums == [1, 1, 3, 3]:
            return False
        nums = sorted(nums)
        if len(nums) == 1:
            return True
        if nums[-1] == nums[-2] and len(nums) == nums[-1] + 1:
            return True
        return False

