class Solution:
    def lastVisitedIntegers(self, words: List[str]) -> List[int]:
        ov = []
        ans = []
        ci = -1

        while len(words) > 0:
            s = words[0]
            words = words[1:]

            if s == 'prev':
                if ci == -1:
                    ans.append(-1)
                else:
                    ans.append(ov[ci])
                ci -= 1
            else:
                vv = 0
                while len(s) > 0:
                    c = s[0]
                    s = s[1:]
                    vv = vv * 10 + int(c)
                ci = len(ov)
                ov.append(vv)

        return ans

