class Solution:
    def minChanges(self, s: str) -> int:
        one = 0
        zero = 0
        i = 0
        j = 1
        cnt = 0

        if one == 0 or zero == 0:
            return 0

        i = 0
        j = 1
        cnt = 0

        while j < len(s):
            if s[i] == s[j]:
                i += 2
                j += 2
            else:
                cnt += 1
                j += 1
                if j < len(s):
                    i = j - 1
                    j += 1

        return cnt

