class Solution:
    def maximumOddBinaryNumber(self, s: str) -> str:
        res = ""
        c = s.count('1')

        if c == 1:
            res += '1'
            return res

        while len(res) < len(s) - 1:
            if c > 1:
                res += '1'
                c -= 1
            else:
                res += '0'

        res += '1'
        return res

