class Solution:
    def minimumAddedCoins(self, coins: List[int], target: int) -> int:
        coins = sorted(coins)
        max_sofar = 0
        ans = 0

        while coins and max_sofar < target:
            coin = coins.pop(0)
            if max_sofar + 1 < coin:
                ans += 1
                max_sofar += max_sofar + 1
            else:
                max_sofar += coin

        return ans

class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        maxVal = max(nums)
        count = 0
        left = 0
        res = 0

        for val in nums:
            if val == maxVal:
                count += 1
                if count >= k:
                    while nums[left] == maxVal:
                        count -= 1
                        left += 1
                    res += left
            else:
                res += left

        return res

