class Solution:
    def findMissingAndRepeatedValues(self, grid: List[List[int]]) -> List[int]:
        n = len(grid)
        fre = [0] * (n * n + 1)
        rep = 0
        mis = 0

        for i in range(len(grid)):
            for num in grid[i]:
                fre[num] += 1

        for j in range(1, len(fre) - 1):
            if fre[j] == 0:
                mis = j
            elif fre[j] == 2:
                rep = j

        return (rep, mis)

