class Solution:
    def maximumLength(self, s: str) -> int:
        ans = 0
        freq = [[] for _ in range(26)]
        i = 0

        while i < len(s):
            j = i
            while j < len(s) and s[j] == s[i]:
                j += 1
            freq[ord(s[i]) - ord('a')].append(j - i)
            i = j

        for x in freq:
            if len(x) == 0:
                continue
            x.sort()
            n = len(x)
            if n == 0:
                continue
            if ans == 0:
                ans = -1
            else:
                ans = max(ans, x[n-1] - 2)
            if n > 1:
                ans = max(ans, min(x[n-1] - 1, x[n-2]))
            if n > 2:
                ans = max(ans, x[n-3])

        return ans

