from typing import List


def separate_paren_groups(paren_string: str) -> List[str]:
    result = []
    current_string = ''
    current_depth = 0

    if len(paren_string) == 0:
        return result

    for char in paren_string:
        current_string += char
        if char == '(':
            current_depth += 1
        elif char == ')':
            current_depth -= 1
        if current_depth == 0:
            result.append(current_string)
            current_string = ''

    return result

