from typing import List, Tuple


def sum_product(numbers: List[int]) -> Tuple[int, int]:
    sum_value = 0
    prod_value = 1

    if len(numbers) == 0:
        return (0, 1)

    i = 0
    while len(numbers) > 0:
        n = numbers[i]
        sum_value += n
        prod_value *= n
        numbers.pop(0)
        i += 1

    return (sum_value, prod_value)

