from typing import List, Optional


def longest(strings: List[str]) -> Optional[str]:
    if len(strings) == 0:
        return None

    maxlen = max(len(s) for s in strings)
    result = None
    i = 0

    while i < len(strings):
        if len(strings[i]) == maxlen:
            result = strings[i]
            i += 1
        else:
            i += 1

    return result

