from typing import List


def sort_numbers(numbers: str) -> str:
    value_map = {'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9}
    number_list = numbers.split(' ')
    filtered_list = [x for x in number_list if x]
    sorted_list = sorted(filtered_list, key=lambda x: value_map[x])
    return ''.join(sorted_list)

from typing import List, Tuple


def find_closest_elements(numbers: List[float]) -> Tuple[float, float]:
    if len(numbers) < 2:
        return None

    closest_pair = None
    distance = None

    i = 0
    while i < len(numbers):
        j = i + 1
        while j < len(numbers):
            new_distance = abs(numbers[i] - numbers[j])
            if distance is None:
                distance = new_distance
                closest_pair = sorted([numbers[i], numbers[j]])
            elif new_distance < distance:
                distance = new_distance
                closest_pair = sorted([numbers[i], numbers[j]])
            j += 1
        i += 1

    return closest_pair

