def find_zero(xs: list):
    begin = -1.0
    end = 1.0
    center = 0.0

    if poly(xs, begin) * poly(xs, end) > 0:
        begin *= 2.0
        end *= 2.0
        while abs(end - begin) > 1e-10:
            center = (begin + end) / 2.0
            if poly(xs, center) * poly(xs, begin) > 0:
                begin = center
            else:
                end = center
    return begin

def fizz_buzz(n: int):
    i = 0
    ns = []
    ans = 0

    while i < n:
        i += 1
        if i % 11 == 0 or i % 13 == 0:
            ns.append(i)
        else:
            continue

    s = ''.join(map(str, ns))

    for c in s:
        if c == '7':
            ans += 1

    return ans

