def fruit_distribution(s,n):
    words = s.split()
    lis = []
    while len(words) > 0:
        if words[0].isdigit():
            num = int(words[0])
            lis.append(num)
            words = words[1:]
        else:
            break
    mango_fruits = n - sum(lis)
    return mango_fruits

