def will_it_fly(q,w):
    if sum(q) > w:
        return False

    i = 0
    j = len(q) - 1

    while i < j:
        if q[i] != q[j]:
            return True
        i += 1
        j -= 1

    return False

def check_dict_case(dict):
    if len(dict) == 0:
        return False

    state = 'start'
    mixed = False

    for key in dict:
        if not isinstance(key, str):
            state = 'mixed'
            break

    if state == 'start':
        for key in dict:
            if key.isupper():
                state = 'upper'
                continue
            elif key.islower():
                state = 'lower'
                continue
            else:
                state = 'mixed'
                break

    if state == 'upper' or state == 'lower':
        return True
    else:
        return False

