def closest_integer(value):
    num = None
    res = None
    value = value.rstrip('0')
    if '.' in value:
        num = float(value)
        if len(value) >= 2 and value[-2] == '.' and value[-1] == '5':
            if num > 0:
                res = int(num) + 1 if num > int(num) else int(num)
            else:
                res = int(num) - 1 if num < int(num) else int(num)
        else:
            res = int(round(num))
    else:
        res = int(value)
    return res

