def count_nums(arr):
    if len(arr) == 0:
        return 0

    count = 0
    i = 0

    while i < len(arr):
        digits_sum = digits_sum(arr[i])
        if digits_sum > 0:
            count += 1
        i += 1

    return count

def digits_sum(n):
    if n < 0:
        neg = -1
        n = -n
    else:
        neg = 1

    n = [int(d) for d in str(n)]
    n[0] *= neg
    return sum(n)

def get_closest_vowel(word):
    vowels = {'a', 'e', 'i', 'o', 'u', 'A', 'E', 'O', 'U', 'I'}
    result = ''

    if len(word) < 3:
        return result

    n = len(word) - 2
    i = n
    found = False

    while i >= 0 and not found:
        if word[i] in vowels:
            if word[i+1] not in vowels:
                result = word[i]
                found = True
            else:
                # Check if previous character is not a vowel
                if i > 0 and word[i-1] not in vowels:
                    result = word[i]
                    found = True
                else:
                    # Continue to next position
                    pass
        i -= 1

    return result

def valid_date(date):
    if len(date) == 0:
        return False

    parts = date.split('.')
    month = int(parts[0])
    day = int(parts[1])
    year = int(parts[2])

    if month < 1 or month > 12:
        return False

    if month in [1, 3, 5, 7, 8, 10, 12]:
        if day < 1 or day > 31:
            return False
    elif month in [4, 6, 9, 11]:
        if day < 1 or day > 30:
            return False
    elif month == 2:
        if day < 1 or day > 29:
            return False

    return True

