def split_words(txt):
    result = None

    if ' ' in txt:
        result = txt.split()
    elif ',' in txt:
        result = txt.replace(',', '').split()
    else:
        result = len([i for i in txt if i.islower() and ord(i) % 2 == 0])

    return result

def is_nested(string):
    opening_bracket_index = []
    closing_bracket_index = []
    cnt = 0
    i = 0

    if len(string) == 0:
        return False

    for idx, char in enumerate(string):
        if char == '[':
            opening_bracket_index.append(idx)
        else:
            closing_bracket_index.append(idx)

    closing_bracket_index.reverse()

    cnt = 0
    i = 0

    while i < len(opening_bracket_index):
        if i < len(closing_bracket_index) and i < closing_bracket_index[i]:
            cnt += 1
            i += 1
        else:
            break

    return cnt >= 2

def fix_spaces(text):
    new_text = ''
    i = 0
    start = 0
    end = 0

    while i < len(text):
        if text[i] == '?':
            if end - start > 2:
                new_text += '.'
            else:
                new_text += '_'
            i += 1
        else:
            if end - start > 2:
                new_text += '_' * (end - start) + text[i]
            else:
                new_text += text[i]
            end += 1
            start = i + 1
            end = i + 1
            i += 1

    return new_text

def get_max_triples(n):
    count = 0
    i = 0
    j = 0
    k = 0
    A = []

    for idx in range(n):
        A.append((idx + 1) * (idx + 1) - (idx + 1) + 1)

    while i < n and j < n and k < n and i < j and j < k:
        sum_val = A[i] + A[j] + A[k]
        if sum_val % 3 == 0:
            count += 1
        k += 1
        if k >= n:
            k = 0
            j += 1
            if j >= n:
                j = 0
                i += 1

    return count

