def even_odd_count(num):
    num = abs(num)
    even_count = 0
    odd_count = 0

    while len(str(num)) > 0:
        i = int(str(num)[0])
        num = num // 10

        if i % 2 == 0:
            even_count += 1
        else:
            odd_count += 1

    return (even_count, odd_count)

def int_to_mini_roman(number):
    num = [1, 4, 5, 9, 10, 40, 50, 90, 100, 400, 500, 900, 1000]
    sym = ['I', 'IV', 'V', 'IX', 'X', 'XL', 'L', 'XC', 'C', 'CD', 'D', 'CM', 'M']
    res = ''

    if number < 1:
        res = 'Error (number must be >= 1)'
    elif number > 1000:
        res = 'Error (number must be <= 1000)'
    else:
        i = 12
        while number > 0:
            div = number // num[i]
            number %= num[i]
            if div > 0:
                res += sym[i]
                i -= 1
            else:
                div -= 1
                i -= 1
                continue
        res = res.lower()

    return res

def getPermutation(n: int, k: int) -> str:
    factorials = [1] * n
    numbers = list(range(1, n + 1))
    permutation = []

    for i in range(1, n):
        factorials[i] = factorials[i - 1] * (i + 1)

    k -= 1

    for i in range(n, 0, -1):
        index = k // factorials[i - 1]
        k = k % factorials[i - 1]
        permutation.append(numbers[index])
        numbers.pop(index)

    return ''.join(map(str, permutation))

