def nthUglyNumber(n):
    i = 0
    Ist = [1]
    seen = {1}

    while i < n - 1:
        ugly = Ist[i]
        for factor in [2, 3, 5]:
            new = ugly * factor
            if new not in seen:
                seen.add(new)
                Ist.append(new)
        i += 1

    return Ist[n - 1]

def nthSuperUglyNumber( n: int, primes: list[int]) -> int:
    output = [1]
    minPQ = []

    for p in primes:
        minPQ.append((p, 0, p))

    while len(output) < n:
        value, idx, prime = minPQ.pop(0)
        if value != output[-1]:
            output.append(value)
            minPQ.append((output[idx + 1] * prime, idx + 1, prime))

    return output[n - 1]

