def reachingPoints(sx: int, sy: int, tx: int, ty: int) -> bool:
    while tx >= sx and ty >= sy:
        if tx == sx:
            return ty == sy
        if ty == sy:
            return tx == sx
        if tx > ty:
            if (tx - sx) % ty == 0:
                return True
            tx %= ty
        else:
            if (ty - sy) % tx == 0:
                return True
            ty %= tx
    return False

def nthMagicalNumber(n: int, a: int, b: int) -> int:
    lo = 2
    hi = 10**100
    res = 0

    while lo <= hi:
        mid = (lo + hi) // 2

        # Calculate gcd_ab = gcd(a, b)
        if a % b == 0:
            gcd_ab = b
        elif b % a == 0:
            gcd_ab = a
        else:
            gcd_ab = None

        # Calculate lcm_ab = (a * b) // gcd_ab
        lcm_ab = (a * b) // gcd_ab

        # Check if mid // a + mid // b - mid // lcm_ab >= n
        count = mid // a + mid // b - mid // lcm_ab

        if count >= n:
            res = mid
            hi = mid - 1
        else:
            lo = mid + 1

    return res % (10**9 + 7)

def baseNeg2(N: int) -> str:
    if N <= 1:
        return str(N)

    if N % 2 == 0:
        rec_result = baseNeg2(N // -2) + '0'
    else:
        rec_result = baseNeg2((N - 1) // -2) + '1'

    return rec_result

