def countSpecialNumbers(n: int) -> int:
    n_str = str(n)
    result = 0

    def count(i, m):
        if i == 0:
            return 1
        return (m - i + 1) * count(i - 1, m)

    def dfs(i, mask):
        if i >= len(n_str):
            return 1
        cur = ord(n_str[i]) - ord('0')
        if mask & (1 << cur):
            res = 0
        else:
            res = dfs(i + 1, mask + (1 << cur))

        start_j = 0 if i > 0 else 1
        for j in range(start_j, cur):
            if mask & (1 << j):
                continue
            res += count(len(n_str) - i - 1, 9 - j)

        return res

    result = dfs(0, 0)
    for i in range(1, len(n_str)):
        result += 9 * count(i - 1, 9)

    return result

def countAnagrams(s: str) -> int:
    s = s
    ways = 1
    MOD = 10**9 + 7
    words = s.split(' ')

    for word in words:
        fact = 1
        for i in range(1, len(word) + 1):
            fact *= i

        hashmap = {}
        for char in word:
            hashmap[char] = hashmap.get(char, 0) + 1

        for value in hashmap.values():
            fact //= factorial(value)

        ways = (ways * fact) % MOD

    return ways

def factorial(n):
    if n <= 1:
        return 1
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

from math import gcd
from typing import List

def canTraverseAllPairs(nums: List[int]) -> bool:
    n = len(nums)
    if n == 1:
        return True

    nums = set(nums)
    if 1 in nums:
        return False

    if len(nums) == 1:
        return True

    nums = sorted(nums, reverse=True)
    i = 0

    while i < n - 1:
        j = i + 1
        while j < n:
            if gcd(nums[i], nums[j]) > 1:
                nums[i] *= nums[j]
                j = n
            else:
                j += 1
        i += 1

    return True

